# Writes the campfire's hedra command files: campfire.txt (stones, logs, ember bed, flickering
# flames) and smoke.txt (one smoke puff with its fire-lit underside, on a seamless rising loop).
# Run from models/env: /usr/bin/python3 make_campfire.py. Up Z, front -Y (hedra); colours are exact
# Fading 16 colours (sRGB 0..1), so the bake snaps them to their ramp steps with no error.
#
# The light on the smoke: both models share one 12-frame (1 s at 12 fps) intensity table I[f]
# (0 dip, 1 normal, 2 flare). The flames scale with it; each puff carries two unlit warm caps on its
# underside (a terracotta band and a tan bottom) that pop out of the puff when the fire is bright
# enough for the puff's height and shrink back inside it otherwise. The scene bakes six instances
# of the puff with phases 0, 1, .. 5 s: whole seconds, so in every puff the caps' 1 s flicker stays in
# step with the flames' (clip frame mod 12 = scene frame mod 12).
import math, random

def hexc(h):
    return tuple(int(h[i:i + 2], 16) / 255 for i in (1, 3, 5))

def col(h, emit=False):
    r, g, b = hexc(h)
    s = f"--base-color {r:.4f} {g:.4f} {b:.4f}"
    return s + (f" --emission {r:.4f} {g:.4f} {b:.4f}" if emit else "")

FPS = 12
I = [2, 1, 1, 0, 1, 2, 1, 2, 0, 1, 2, 1]      # fire intensity per frame of the 1 s flicker loop

# ------------------------------------------------------------------ campfire
random.seed(4)
cf = [f"""# Campfire: a ring of seven stones (r 0.42), three logs leaning into a teepee, a glowing ember bed,
# a flame base and three flame tongues. Stones and logs are lit; embers and flames are emissive
# (unlit splats). Each tongue is its own object (one bone): stepped scale and sway keys on a 1 s loop
# (12 frames, constant), following the intensity table I = {I} (frame 0 = a flare: the
# largest pose, which the bake samples). Generated by make_campfire.py. Up Z; origin = the fire's
# centre on the ground.
new
fps {FPS}
frame range 0 12
material new Stone {col('#8c7c79')} --no-slot
material new Log {col('#846d59')} --no-slot
material new Embers {col('#9c524e', True)} --no-slot
material new FlameBase {col('#b97a60', True)} --no-slot
material new FlameCore {col('#ddcf99', True)} --no-slot
material new FlameOuter {col('#cca87b', True)} --no-slot
"""]
stones = []
for i in range(7):
    a = math.radians(i * 360 / 7 + random.uniform(-8, 8))
    r = 0.42 + random.uniform(-0.02, 0.03)
    n = f"Stone{i}"; stones.append(n)
    cf.append(f"""add mesh ico-sphere --name {n} --subdivisions 1 --radius 0.12 --location {r * math.cos(a):.3f} {r * math.sin(a):.3f} 0.06
scale {random.uniform(1.0, 1.25):.2f} {random.uniform(0.9, 1.1):.2f} 0.7
apply --scale
""")
cf.append("select " + " ".join(stones) + "\nactive Stone0\njoin\nrename Stone0 Stones\nmaterial assign Stone\n"
          "mode edit\nselect all\nrandomize --amount 0.02 --seed 5\nmode object\n")
# logs: 0.62 m long, 0.15 thick, feet on the ring's inside, tops meeting over the centre
logs = []
for i, a in enumerate((20, 140, 260)):
    n = f"Log{i}"; logs.append(n)
    ar = math.radians(a)
    cx, cy = 0.12 * math.cos(ar), 0.12 * math.sin(ar)
    # a log along X, tilted 40 degrees up towards the centre, then turned to face it
    cf.append(f"""add mesh cylinder --name {n} --vertices 6 --radius 0.075 --depth 0.62 --location 0 0 0 --rotation 0 90 0
apply --rotation
set rotation 0 -40 {a + 180}
apply --rotation
set location {cx:.3f} {cy:.3f} 0.2
apply --location
""")
cf.append("select " + " ".join(logs) + "\nactive Log0\njoin\nrename Log0 Logs\nmaterial assign Log\n")
cf.append(f"""add mesh cylinder --name Embers --vertices 8 --radius 0.27 --depth 0.06 --location 0 0 0.03
material assign Embers
add mesh cone --name FlameBase --vertices 7 --radius1 0.25 --radius2 0.05 --depth 0.44 --location 0 0 0.25
material assign FlameBase
""")
# tongues: (name, material, x, y, radius, height, z base, own jitter pattern on top of I)
TONGUES = [
    ("TongueA", "FlameCore", 0.0, 0.0, 0.13, 0.85, 0.08),
    ("TongueB", "FlameOuter", 0.1, 0.07, 0.12, 0.68, 0.08),
    ("TongueC", "FlameOuter", -0.1, -0.06, 0.12, 0.6, 0.08),
]
HS = {0: 0.55, 1: 0.78, 2: 1.0}     # height scale per intensity
for k, (n, m, x, y, r, h, zb) in enumerate(TONGUES):
    cf.append(f"""add mesh cone --name {n} --vertices 6 --radius1 {r} --radius2 0.01 --depth {h} --location {x} {y} {zb + h / 2:.3f}
material assign {m}
cursor set {x} {y} {zb}
origin set --to cursor
""")
for k, (n, m, x, y, r, h, zb) in enumerate(TONGUES):
    rnd = random.Random(20 + k)
    cf.append(f"select {n}\n")
    for f in range(13):
        i = I[f % 12]
        if f % 12 == 0:
            sz, sxy, dx, dy = 1.0, 1.0, 0.0, 0.0
        else:
            sz = HS[i] * rnd.uniform(0.82, 1.0)
            sxy = rnd.uniform(0.85, 1.0)
            dx, dy = rnd.uniform(-0.03, 0.03), rnd.uniform(-0.03, 0.03)
        if f == 12:
            sz, sxy, dx, dy = 1.0, 1.0, 0.0, 0.0
        cf.append(f"frame set {f}\nset location {x + dx:.3f} {y + dy:.3f} {zb}\nset scale {sxy:.2f} {sxy:.2f} {sz:.2f}\n"
                  "keyframe insert --channels loc,scale\n")
    cf.append("keyframe interpolation constant --all\n")
cf.append("""frame set 0
select all
shade flat
export campfire.glb --bake-animations
""")
open("campfire.txt", "w").write("".join(cf))

# ------------------------------------------------------------------ smoke puff
# Life t in 0..1 over T = 6 s (72 frames): the puff is born at the flames' tips (z 0.85, scale 0.35),
# rises 2.0 m at constant speed drifting 0.35 m along -X (the wind) with a little wobble, grows to
# full size at t 0.75, then shrinks to 0.15 at the top and is reborn. Frame 0 is t 0.75, its full
# size: the bake samples the splats at frame 0 (a smaller puff would be thin when it grows).
R = 0.32
T_FRAMES = 72
def life(c):
    return (0.75 + c / T_FRAMES) % 1.0

def pen(t):
    """how far the fire's light fades with the puff's height: 0 low, 3 out of reach"""
    return 0 if t < 0.22 else 1 if t < 0.42 else 2 if t < 0.6 else 3

DIM_ON, DIM_OFF = 1.0, 0.82        # the terracotta band: radius 1.12 R, z < 0.1 R
BRIGHT_ON, BRIGHT_OFF = 1.0, 0.78  # the tan bottom: radius 1.2 R, z < -0.35 R
sm = [f"""# One smoke puff (a jittered icosphere, r {R} at full size) on a seamless {T_FRAMES // FPS} s rising loop, lit by the sun,
# with two emissive caps on its underside that catch the fire's light: Glow (terracotta, its lower
# half below z 0.1 r, radius 1.12 r) and Hot (tan, below z -0.35 r, radius 1.2 r). A cap is ON when it is out of
# the puff (scale 1) and OFF shrunk inside it ({DIM_OFF} / {BRIGHT_OFF}). Per frame, brightness B = I[frame mod 12] + 1 -
# fade(height) (fade 0 low, 1, 2, 3 out of reach): Glow on when B >= 1, Hot when B >= 2, so the lowest
# puffs glow on every frame and flare tan with the flames, the middle ones only on the fire's flares,
# the top ones never. Frame 0 is t 0.75 (full size, caps off). Keys on every frame (constant).
# Generated by make_campfire.py. Up Z; origin = the birth point, the fire's centre on the ground.
new
fps {FPS}
frame range 0 {T_FRAMES}
material new Smoke {col('#8c7c79')} --no-slot
material new Glow {col('#b97a60', True)} --no-slot
material new Hot {col('#cca87b', True)} --no-slot
add mesh ico-sphere --name Puff --subdivisions 2 --radius {R} --location 0 0 0
material assign Smoke
mode edit
select all
randomize --amount 0.04 --seed 6
mode object
add mesh ico-sphere --name Glow --subdivisions 3 --radius {R * 1.12:.4f} --location 0 0 0
material assign Glow
mode edit
select vert where "pos.z > {0.1 * R:.4f}"
delete vert
mode object
add mesh ico-sphere --name Hot --subdivisions 3 --radius {R * 1.2:.4f} --location 0 0 0
material assign Hot
mode edit
select vert where "pos.z > {-0.35 * R:.4f}"
delete vert
mode object
select Glow Hot Puff
active Puff
parent set Puff
"""]
def puff_pose(c):
    t = life(c)
    z = 0.85 + 2.0 * t
    x = -0.35 * t + 0.05 * math.sin(2 * math.pi * 2 * t)
    y = 0.04 * math.sin(2 * math.pi * 1.3 * t)
    s = 0.35 + 0.65 * t / 0.75 if t <= 0.75 else 1.0 - 0.85 * (t - 0.75) / 0.25
    return x, y, z, s

sm.append("select Puff\n")
for c in range(T_FRAMES + 1):
    x, y, z, s = puff_pose(c % T_FRAMES)
    sm.append(f"frame set {c}\nset location {x:.4f} {y:.4f} {z:.4f}\nset scale {s:.4f} {s:.4f} {s:.4f}\n"
              "keyframe insert --channels loc,scale\n")
sm.append("keyframe interpolation constant --all\n")
for name, need, on, off in (("Glow", 1, DIM_ON, DIM_OFF), ("Hot", 2, BRIGHT_ON, BRIGHT_OFF)):
    sm.append(f"select {name}\n")
    for c in range(T_FRAMES + 1):
        cc = c % T_FRAMES
        b = I[cc % 12] + 1 - pen(life(cc))
        v = on if b >= need else off
        sm.append(f"frame set {c}\nset scale {v} {v} {v}\nkeyframe insert --channels scale\n")
    sm.append("keyframe interpolation constant --all\n")
sm.append("""frame set 0
select all
shade flat
export smoke.glb --bake-animations
""")
open("smoke.txt", "w").write("".join(sm))
print("wrote campfire.txt smoke.txt")
